/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, Easing } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ChartAnimationProps = Record<string, any>;

const ChartAnimation: React.FC<ChartAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  titleOurProduct = "Our product",
  titleCompetition = "Competition",
  colorOurProductStart = "#8b5cf6",
  colorOurProductEnd = "#f87171",
  colorCompetition = "#94a3b8",
  axisColor = "#ffffff",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const startX = width * 0.15;
  const chartWidth = width * 0.65;
  const startY = height * 0.8;
  const chartHeight = height * 0.6;

  // Timing constants relative to duration
  const durationInFrames = durationInSeconds * fps;
  const axisDrawEnd = Math.round(durationInFrames * 0.1);
  const labelsFadeStart = Math.round(durationInFrames * 0.05);
  const labelsFadeEnd = Math.round(durationInFrames * 0.15);
  const linesDrawStart = Math.round(durationInFrames * 0.1);
  const linesDrawEnd = Math.round(durationInFrames * 0.7);
  const endLabelsStart = Math.round(durationInFrames * 0.6);
  const endLabelsEnd = Math.round(durationInFrames * 0.8);

  // Path Generation - Mathematical asymptotic curve
  const generatePath = (sx: number, sy: number, w: number, h: number, steepness: number, maxY: number) => {
    let d = "";
    const numPoints = 100;
    for (let i = 0; i <= numPoints; i++) {
      const x = sx + (i / numPoints) * w;
      // y = max * (1 - e^(-k * x))
      const yVal = maxY * (1 - Math.exp(-steepness * (i / numPoints)));
      const y = sy - yVal;
      d += `${i === 0 ? "M" : "L"} ${x},${y} `;
    }
    return d.trim();
  };

  // Memoized path generation to prevent recalculation every frame
  const pathOurProduct = useMemo(
    () => generatePath(startX, startY, chartWidth, chartHeight, 4.5, chartHeight * 0.9),
    [startX, startY, chartWidth, chartHeight]
  );
  const pathCompetition = useMemo(
    () => generatePath(startX, startY, chartWidth, chartHeight, 3.5, chartHeight * 0.55),
    [startX, startY, chartWidth, chartHeight]
  );

  // Interpolations
  const yAxisProgress = interpolate(frame, [0, axisDrawEnd], [0, chartHeight], {
    extrapolateRight: "clamp",
  });
  const xAxisProgress = interpolate(frame, [0, axisDrawEnd], [0, chartWidth], {
    extrapolateRight: "clamp",
  });

  const labelsOpacity = interpolate(frame, [labelsFadeStart, labelsFadeEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const endLabelsOpacity = interpolate(frame, [endLabelsStart, endLabelsEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const progressOurProduct = interpolate(frame, [linesDrawStart, linesDrawEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  
  const progressCompetition = interpolate(frame, [linesDrawStart, linesDrawEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Calculate drawing bounds for SVG paths
  const evolutionOurProduct = evolvePath(progressOurProduct, pathOurProduct);
  const evolutionCompetition = evolvePath(progressCompetition, pathCompetition);

  // Exact endpoint Y coordinates for placing the end labels
  const endYOurProduct = startY - chartHeight * 0.9 * (1 - Math.exp(-4.5));
  const endYCompetition = startY - chartHeight * 0.55 * (1 - Math.exp(-3.5));

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          overflow: "visible",
        }}
      >
        <defs>
          <linearGradient id="productGradient" x1="0%" y1="100%" x2="100%" y2="0%">
            <stop offset="0%" stopColor={colorOurProductStart} />
            <stop offset="100%" stopColor={colorOurProductEnd} />
          </linearGradient>
        </defs>

        {/* Axes */}
        <line
          x1={startX}
          y1={startY}
          x2={startX}
          y2={startY - yAxisProgress}
          stroke={axisColor}
          strokeWidth={4}
          strokeLinecap="round"
        />
        <line
          x1={startX}
          y1={startY}
          x2={startX + xAxisProgress}
          y2={startY}
          stroke={axisColor}
          strokeWidth={4}
          strokeLinecap="round"
        />

        {/* Competition Line */}
        <path
          d={pathCompetition}
          fill="none"
          stroke={colorCompetition}
          strokeWidth={6}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolutionCompetition.strokeDasharray}
          strokeDashoffset={evolutionCompetition.strokeDashoffset}
        />

        {/* Our Product Line */}
        <path
          d={pathOurProduct}
          fill="none"
          stroke="url(#productGradient)"
          strokeWidth={10}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolutionOurProduct.strokeDasharray}
          strokeDashoffset={evolutionOurProduct.strokeDashoffset}
        />
      </svg>

      {/* Y Axis Label & Ticks */}
      <div
        style={{
          position: "absolute",
          left: startX - 100,
          top: startY - chartHeight / 2,
          transform: "translate(-50%, -50%) rotate(-90deg)",
          color: textColor,
          fontSize: 24,
          letterSpacing: 1.5,
          opacity: labelsOpacity,
          transition: "none",
        }}
      >
        Performance
      </div>
      {[0, 50, 100].map((val, i) => (
        <div
          key={`y-tick-${val}`}
          style={{
            position: "absolute",
            left: startX - 20,
            top: startY - (chartHeight / 2) * i,
            transform: "translate(-100%, -50%)",
            color: "#94a3b8",
            fontSize: 20,
            opacity: labelsOpacity,
            transition: "none",
          }}
        >
          {val}
        </div>
      ))}

      {/* X Axis Label & Ticks */}
      <div
        style={{
          position: "absolute",
          left: startX + chartWidth / 2,
          top: startY + 80,
          transform: "translate(-50%, -50%)",
          color: textColor,
          fontSize: 24,
          letterSpacing: 1.5,
          opacity: labelsOpacity,
          transition: "none",
        }}
      >
        Time (s)
      </div>
      {[0, 20, 40, 60, 80, 100].map((val, i) => (
        <div
          key={`x-tick-${val}`}
          style={{
            position: "absolute",
            left: startX + (chartWidth / 5) * i,
            top: startY + 30,
            transform: "translate(-50%, 0)",
            color: "#94a3b8",
            fontSize: 20,
            // Hides 40 to match exact visual rhythm of the reference image
            opacity: val === 40 ? 0 : labelsOpacity,
            transition: "none",
          }}
        >
          {val}
        </div>
      ))}

      {/* Line Labels */}
      <div
        style={{
          position: "absolute",
          left: startX + chartWidth + 30,
          top: endYOurProduct,
          transform: "translate(0, -50%)",
          color: textColor,
          fontSize: 40,
          fontWeight: "bold",
          opacity: endLabelsOpacity,
          transition: "none",
          whiteSpace: "nowrap",
        }}
      >
        {titleOurProduct}
      </div>
      <div
        style={{
          position: "absolute",
          left: startX + chartWidth + 30,
          top: endYCompetition,
          transform: "translate(0, -50%)",
          color: textColor,
          fontSize: 40,
          fontWeight: "bold",
          opacity: endLabelsOpacity,
          transition: "none",
          whiteSpace: "nowrap",
        }}
      >
        {titleCompetition}
      </div>
    </AbsoluteFill>
  );
};

export default ChartAnimation;